{
  "ledger": {
    "p73:e573": {
      "state": "represented",
      "fact_ids": ["P0073F0001"],
      "note": "결과는 no Pinning이 가장 빠르다는 기록이 P0073F0001로 보존됨. 구체적 수치와 이유는 후속 항목(p73:e575~p73:e581, p73:img0:e2)에서 다루어짐."
    },
    "p73:e574": {
      "state": "no_research",
      "fact_ids": [],
      "note": "단순 감탄사('흠 ..')로 연구 내용 없음."
    },
    "p73:e575": {
      "state": "no_research",
      "fact_ids": [],
      "note": "섹션 제목('① cudaHostAlloc이 8.64초 더 걸린 이유')이며 실제 설명 내용은 후속 문단 p73:e576에 있음."
    },
    "p73:e576": {
      "state": "represented",
      "fact_ids": ["P0073F0002"],
      "note": "CPU 루프 내 복사 오버헤드(8.64초, 회당 약 9.4μs, 92만 번 수행)로 cudaHostAlloc 추가 소요를 해석한 내용이 P0073F0002로 보존됨."
    },
    "p73:e577": {
      "state": "no_research",
      "fact_ids": [],
      "note": "섹션 제목('② No Pinning과 Pinned 메모리 차이가 크지 않은 이유')이며 실제 내용은 후속 항목 p73:e578~p73:e580에 있음."
    },
    "p73:e578": {
      "state": "no_research",
      "fact_ids": [],
      "note": "서브 제목('1. 극도로 작은 입력 크기 (1 KB)')이며 실제 내용은 후속 문단 p73:e579에 있음."
    },
    "p73:e579": {
      "state": "represented",
      "fact_ids": ["P0073F0003"],
      "note": "입력 벡터 크기 1024Byte(1KB), CPU L1/L2 캐시, 드라이버 스테이징 버퍼 복사 지연 0.1μs 미만 등 내용이 P0073F0003에 보존됨."
    },
    "p73:e580": {
      "state": "represented",
      "fact_ids": ["P0073F0003"],
      "note": "GPU 연산 시간 지배적(Amdahl's Law), 단일 샘플 처리 시간 ~840μs 중 85% 이상(약 716μs)이 순수 GPU 커널 연산, 전송 시간 비중 1~2μs 수준 등 내용이 P0073F0003에 보존됨."
    },
    "p73:e581": {
      "state": "represented",
      "fact_ids": ["P0073F0004"],
      "note": "No pinning이 pinned memory보다 더 빠른 이유에 대한 추가 상세 분석 의도가 P0073F0004로 보존됨. 실측 결론은 아니며 분석 방향 제시임."
    },
    "p73:img0:e0": {
      "state": "no_research",
      "fact_ids": [],
      "note": "벤치마크 결과 비교 섹션 제목('1. 3가지 메모리 방식 벤치마크 결과 비교')이며 실제 표는 p73:img0:e2에 있음."
    },
    "p73:img0:e1": {
      "state": "represented",
      "fact_ids": ["P0073F0005"],
      "note": "벤치마크 조건(backward_only method=2, CUDA Graph Separate graph_mode=1, 총 920,000회 연산)이 P0073F0005의 conditions로 보존됨."
    },
    "p73:img0:e2": {
      "state": "represented",
      "fact_ids": ["P0073F0005"],
      "note": "3가지 메모리 방식 벤치마크 결과 비교표 전체가 P0073F0005로 보존됨. 전체 실행 시간, 추론/바운드 누적 시간, 평균/중위/꼬리 지연, 지터, 순수 GPU 커널 시간, 처리량 등 모든 행·셀 값이 보존됨. structured_table_manifest에 complete=true로 등록됨."
    }
  }
}
